// Generates tokens.css from the jinteki.win design system's tokens.json
// (the published design system ships tokens.json but not tokens.css).
// Usage: node public/shared/jw/build-tokens.mjs
// Token names are used exactly as in tokens.json. A theme without its own
// value for a colour inherits the first theme's value, as the design system
// specifies. Do not edit tokens.css by hand; re-run this script instead.
import { readFileSync, writeFileSync } from 'node:fs';

const dir = new URL('./', import.meta.url);
const t = JSON.parse(readFileSync(new URL('tokens.json', dir), 'utf8'));
const themes = t.color.themes.map((x) => x.id);
const first = themes[0];

const valueFor = (tok, theme) => {
  if (typeof tok.value === 'string') return tok.value;
  return tok.value[theme] ?? tok.value[first];
};

const out = [
  '/* jinteki.win design system tokens. Generated by build-tokens.mjs from tokens.json. Do not edit. */',
];
for (const theme of themes) {
  const sel = theme === first ? `:root, [data-theme="${theme}"]` : `[data-theme="${theme}"]`;
  const lines = t.color.tokens.map((tok) => `  --${tok.name}: ${valueFor(tok, theme)};`);
  for (const tok of t.shadow?.tokens ?? []) lines.push(`  --${tok.name}: ${valueFor(tok, theme)};`);
  out.push(`${sel} {\n${lines.join('\n')}\n}`);
}
const shared = [];
for (const fam of ['spacing', 'radius']) {
  for (const tok of t[fam]?.tokens ?? []) shared.push(`  --${tok.name}: ${tok.value};`);
}
out.push(`:root {\n${shared.join('\n')}\n}`);
writeFileSync(new URL('tokens.css', dir), out.join('\n\n') + '\n');
console.log(`tokens.css: ${themes.length} themes, ${t.color.tokens.length} colour tokens`);
